const SimulatorAndProduction = ({ windows, setWindows, hasRun, setHasRun, orderNo, results, totals }) => {
  const tableRef = useRef(null);
  const updateWindow = (id, field, value) =>
    setWindows((prev) => prev.map((w) => (w.id === id ? { ...w, [field]: value } : w)));
