                <div className="grid grid-cols-2 text-sm">
                  <div className="px-4 py-2 font-medium text-slate-600 border-b border-r border-slate-100">Property</div>
                  <div className="px-4 py-2 font-semibold text-slate-800 border-b border-slate-100">{r.wno}</div>
                  <div className="px-4 py-2 font-medium text-slate-600 border-b border-r border-slate-100">shutterWidth</div>
                  <div className="px-4 py-2 text-slate-800 border-b border-slate-100">{fmt(r.shutterWidth)}</div>
                  <div className="px-4 py-2 font-medium text-slate-600 border-b border-r border-slate-100">shutterHeight</div>
