                  <div className="px-4 py-2 text-slate-800 border-b border-slate-100">{fmt(totals.fixFrameBars)}</div>
                  <div className="px-4 py-2 font-medium text-slate-600 border-b border-r border-slate-100">opBeadBars</div>
                  <div className="px-4 py-2 text-slate-800 border-b border-slate-100">{fmt(totals.opBeadBars)}</div>
            </div>
          </div>
        </Card>
      )}
    </div>
  );
};

