    const nextNum = windows.length + 1;
    setWindows((prev) => [...prev, { id: Date.now(), wno: `W${nextNum}`, width: "", height: "", qty: "1" }]);
  };
  const removeWindow = (id) =>
    setWindows((prev) => {
