/* ------------------------------------------------------------------
   FORMULA LOGIC  (ported 1:1 from SL-SL(Small Sash) / Profile & Hardwares sheets)
   ------------------------------------------------------------------
   shutterWidth      = IF(Width=="", "", (Width - 40) / 2)              -> SL-SL!D6
   shutterHeight     = IF(Height=="", "", (Height - 103))               -> SL-SL!E6
   meshSashFramBars  = CEILING((((SUM(Width)+SUM(Height))*2)/5850),0.1) -> SL-SL!H6
   meshSashBars      = CEILING((((SUM(shutterWidth)*4)+(SUM(shutterHeight)*4))/5850),0.1)
                                                                          -> SL-SL!H7
   windowCount       = COUNTA(W.No column)                              -> SL-SL!A17
   rollerCount       = windowCount * 4                                  -> Hardware!O18
   gasLength         = (meshSashBars * 5900) / 1000                     -> Hardware!O10 / O12
   ------------------------------------------------------------------
   NOTE: meshSashFramBars and meshSashBars depend on the SUM of Width/
   Height/shutterWidth/shutterHeight across ALL rows, not on a single
   row. They are therefore computed once for the whole order (totals),
   not per-window — this mirrors the spreadsheet, where H6/H7 reference
   B17:E17 (column totals), not individual rows.
   ------------------------------------------------------------------ */

const computeWindow = (w) => {
  const width = Number(w.width) || 0;
  const height = Number(w.height) || 0;

  const shutterWidth = width === 0 ? 0 : (width - 40) / 2;
  const shutterHeight = height === 0 ? 0 : height - 103;

  return { shutterWidth, shutterHeight };
};

// Order-level totals (mirrors row 17 + H6/H7 of the SL-SL(Small Sash) sheet)
const computeTotals = (results) => {
  const sumWidth = results.reduce((acc, r) => acc + (Number(r.width) || 0) * (Number(r.qty) || 1), 0);
  const sumHeight = results.reduce((acc, r) => acc + (Number(r.height) || 0) * (Number(r.qty) || 1), 0);
  const sumShutterWidth = results.reduce((acc, r) => acc + (r.shutterWidth || 0) * (Number(r.qty) || 1), 0);
  const sumShutterHeight = results.reduce((acc, r) => acc + (r.shutterHeight || 0) * (Number(r.qty) || 1), 0);
  const windowCount = results.reduce((acc, r) => acc + (Number(r.qty) || 1), 0);

  const rawFram = ((sumWidth + sumHeight) * 2) / 5850;
  const meshSashFramBars = rawFram === 0 ? 0 : Math.ceil(rawFram * 10) / 10;

  const rawSash = (sumShutterWidth * 4 + sumShutterHeight * 4) / 5850;
  const meshSashBars = rawSash === 0 ? 0 : Math.ceil(rawSash * 10) / 10;

  const rollerCount = windowCount * 4;
  const gasLength = (meshSashBars * 5900) / 1000;

  return {
    meshSashFramBars,
    meshSashBars,
    windowCount,
    rollerCount,
    gasLength,
  };
};

