      `[data-row="${rowIdx}"][data-col="${colIdx}"]`
    );
    if (el) el.focus();
  };

  const handleKeyDown = (e, rowIdx, colIdx) => {
    if (e.key !== "Enter") return;
    e.preventDefault();

