/* ------------------------------------------------------------------
   FORMULA LOGIC  (ported 1:1 from Single Open / Profile & Hardwares sheets)
   ------------------------------------------------------------------
   Per-row inputs: Width(mm), Height(mm)

   Shutter columns (D / E of Single Open sheet):
     shutterWidth   = IF(Width=="",  "", Width  - 60)           → D6
     shutterHeight  = IF(Height=="", "", Height - 60)           → E6

   Steel sub-table columns (K / L):
     framWidth      = IF(Width=="",         "", Width - 90)     → K6
     sashWidth      = IF(shutterWidth=="",  "", shutterWidth - 125) → L6

   Glass sub-table columns (O / P / Q / T):
     glassWidth     = IF(shutterWidth=="",  "", shutterWidth  - 125) → O6
     glassHeight    = IF(shutterHeight=="", "", shutterHeight - 125) → P6
     glassNos       = IF(sqft=="", "", 1)                           → Q6
     sqft           = IF(glassWidth=="", "",
                        CEILING(glassWidth/304.8,0.25) *
                        CEILING(glassHeight/304.8,0.25))            → T6

   Order-level totals (row 17 / Profile Required table col H):
     opFramBars = CEILING(((SUM(Width)+SUM(Height))*2)/5850, 0.1)             → H6
     opSashBars = CEILING(((SUM(shutterWidth)*2)+(SUM(shutterHeight)*2))/5850, 0.1) → H7
     opBeadBars = opSashBars                                                  → H8 (=H7)
     framSteel  = CEILING(((SUM(framWidth)*2)+500)/2438, 0.1)                 → H10
     sashSteel  = CEILING((SUM(sashWidth)*2)/2438, 0.1)                       → H11
     totalSqft  = SUM(sqft) * 2                                               → T17

   Espage & Friction Stay size counts (rows 22–32 / col B–F, summed at row 33):
     espage800Count  = COUNT rows where shutterHeight in (845, 1066)           → B33
     espage1000Count = COUNT rows where shutterHeight in (1065, 1265)          → C33
     fs10Count       = COUNT rows where Width in (350, 491)                    → D33
     fs12Count       = COUNT rows where Width in (490, 641)                    → E33
     fs14Count       = COUNT rows where Width in (640, 841)                    → F33

   Hardware (Profile & Hardwares sheet col G):
     casmentHandel  = windowCount * 1                                          → G14
     espage800      = espage800Count                                           → G15
     espage1000     = espage1000Count                                          → G16
     frictionStay10 = fs10Count                                                → G17
     frictionStay12 = fs12Count                                                → G18
     gasFlatType    = ((opFramBars + opBeadBars) * 5900) / 1000               → G19
     gasZeroType    = (opSashBars * 5900) / 1000                              → G20
     gasZeroNonType = gasZeroType                                              → G21 (=G20)
     espag600       = 0  (unlinked — Espag 600 Nos)                           → G22
     espag1200      = 0  (unlinked — Espag 1200 Nos)                          → G23
     frictionStay8  = 0  (unlinked — Friction Stay 8" Set)                    → G24
     frictionStay14 = fs14Count                                                → G25
   ------------------------------------------------------------------ */

const computeWindow = (w) => {
  const width  = Number(w.width)  || 0;
  const height = Number(w.height) || 0;

  // Single-panel: Width - 60
  const shutterWidth  = width  === 0 ? 0 : width  - 60;
  const shutterHeight = height === 0 ? 0 : height - 60;

  // Steel sub-table
  const framWidth = width        === 0 ? 0 : width        - 90;
  const sashWidth = shutterWidth === 0 ? 0 : shutterWidth - 125;

  // Glass sub-table
  const glassWidth  = shutterWidth  === 0 ? 0 : shutterWidth  - 125;
  const glassHeight = shutterHeight === 0 ? 0 : shutterHeight - 125;
  const sqft =
    glassWidth === 0
      ? 0
      : (Math.ceil((glassWidth  / 304.8) * 4) / 4) *
        (Math.ceil((glassHeight / 304.8) * 4) / 4);
  const glassNos = sqft === 0 ? 0 : 1;

  return { shutterWidth, shutterHeight, framWidth, sashWidth, glassWidth, glassHeight, glassNos, sqft };
};

// Order-level totals (mirrors row 17 / row 33 of Single Open sheet)
const computeTotals = (results) => {
  const sumWidth         = results.reduce((a, r) => a + (Number(r.width) || 0) * (Number(r.qty) || 1), 0);
  const sumHeight        = results.reduce((a, r) => a + (Number(r.height) || 0) * (Number(r.qty) || 1), 0);
  const sumShutterWidth  = results.reduce((a, r) => a + (r.shutterWidth || 0) * (Number(r.qty) || 1), 0);
  const sumShutterHeight = results.reduce((a, r) => a + (r.shutterHeight || 0) * (Number(r.qty) || 1), 0);
  const sumFramWidth     = results.reduce((a, r) => a + (r.framWidth || 0) * (Number(r.qty) || 1), 0);
  const sumSashWidth     = results.reduce((a, r) => a + (r.sashWidth || 0) * (Number(r.qty) || 1), 0);
  const sumSqft          = results.reduce((a, r) => a + (r.sqft || 0) * (Number(r.qty) || 1), 0);
  const windowCount = results.reduce((acc, r) => acc + (Number(r.qty) || 1), 0);

  const ceil1 = (x) => (x === 0 ? 0 : Math.ceil(x * 10) / 10);

  // Profile Required table (H6–H11)
  const opFramBars = ceil1(((sumWidth + sumHeight) * 2) / 5850);
  const opSashBars = ceil1(((sumShutterWidth * 2) + (sumShutterHeight * 2)) / 5850);
  const opBeadBars = opSashBars;                                        // H8 = H7
  const framSteel  = ceil1(((sumFramWidth * 2) + 500) / 2438);
  const sashSteel  = ceil1((sumSashWidth * 2) / 2438);

  // Single-panel: sqft total * 2
  const totalSqft = sumSqft * 2;

  // Espage / Friction Stay counts (B33–F33)
  const espage800Count  = results.filter(r => r.shutterHeight > 845  && r.shutterHeight < 1066).length;
  const espage1000Count = results.filter(r => r.shutterHeight > 1065 && r.shutterHeight < 1265).length;
  const fs10Count       = results.filter(r => (Number(r.width) || 0) > 350 && (Number(r.width) || 0) < 491).length;
  const fs12Count       = results.filter(r => (Number(r.width) || 0) > 490 && (Number(r.width) || 0) < 641).length;
  const fs14Count       = results.filter(r => (Number(r.width) || 0) > 640 && (Number(r.width) || 0) < 841).length;

  // Hardware (G14–G25)
  const casmentHandel  = windowCount * 1;                               // G14 = A17 (window count)
  const espage800      = espage800Count;                                // G15 = B33
  const espage1000     = espage1000Count;                               // G16 = C33
  const frictionStay10 = fs10Count;                                     // G17 = D33
  const frictionStay12 = fs12Count;                                     // G18 = E33
  const gasFlatType    = ((opFramBars + opBeadBars) * 5900) / 1000;    // G19 (no mullion term)
  const gasZeroType    = (opSashBars * 5900) / 1000;                   // G20
  const gasZeroNonType = gasZeroType;                                   // G21 = G20
  const espag600       = 0;                                             // G22 — unlinked
  const espag1200      = 0;                                             // G23 — unlinked
  const frictionStay8  = 0;                                             // G24 — unlinked
  const frictionStay14 = fs14Count;                                     // G25 = F33

  return {
    windowCount,
    opFramBars,
    opSashBars,
    opBeadBars,
    framSteel,
    sashSteel,
    totalSqft,
    casmentHandel,
    espage800,
    espage1000,
    frictionStay10,
    frictionStay12,
    gasFlatType,
    gasZeroType,
    gasZeroNonType,
    espag600,
    espag1200,
    frictionStay8,
    frictionStay14,
  };
};

