                  <div className="px-4 py-2 text-slate-800 border-b border-slate-100">{r.width}</div>
                  <div className="px-4 py-2 font-medium text-slate-600 border-r border-slate-100">Fram Height</div>
                  <div className="px-4 py-2 text-slate-800">{r.height}</div>
                </div>

                {/* General — per-window computed rules */}
                <div className="px-4 py-2 text-center font-semibold text-slate-600 text-xs uppercase tracking-wide bg-slate-50 border-y border-slate-200">
