  Table2,
  ClipboardList,
  Settings2,
  Layers,
} from "lucide-react";

/* ------------------------------------------------------------------
   FORMULA LOGIC  (ported 1:1 from OP-OP / Profile & Hardwares sheets
   of "OP-OP_Breeze_Production.xlsx")
   ------------------------------------------------------------------
   Per-row (Width, Height inputs):
     shutterWidth  = IF(Width=="", "", (Width / 2) - 37)        -> OP-OP!D6
     shutterHeight = IF(Height=="", "", (Height - 60))          -> OP-OP!E6
     mullionHeight = IF(Height=="", "", (Height - 82))          -> OP-OP!K6
     framWidth     = IF(Width=="", "", (Width - 90))            -> OP-OP!L6
     sashWidth     = IF(shutterWidth=="", "", (shutterWidth - 125)) -> OP-OP!M6
     glassWidth    = IF(shutterWidth=="", "", shutterWidth - 125)   -> OP-OP!P6
     glassHeight   = IF(shutterHeight=="", "", (shutterHeight - 125)) -> OP-OP!Q6
     glassNos      = IF(glassWidth=="", "", 2)                  -> OP-OP!R6
     sqft          = IF(glassWidth=="", "",
                       CEILING(glassWidth/304.8,0.25) *
                       CEILING(glassHeight/304.8,0.25))         -> OP-OP!U6

   Order-level totals (sums across all rows, row 17 / 33):
     opFramBars  = CEILING(((SUM(Width)+SUM(Height))*2)/5850,0.1)              -> H6
     opSashBars  = CEILING(((SUM(shutterWidth)*4)+(SUM(shutterHeight)*4))/5850,0.1) -> H7
     opBeadBars  = opSashBars                                                  -> H8 (=H7)
     mullionBars = CEILING((SUM(mullionHeight))/5850,0.1)                      -> H9
     framSteel   = CEILING(((SUM(framWidth)*2)+500)/2438,0.1)                  -> H11
     sashSteel   = CEILING((SUM(sashWidth)*4)/2438,0.1)                        -> H12
     totalSqft   = SUM(sqft) * 2                                               -> U17

     espage800Count  = COUNT of rows where shutterHeight in (845,1066)  -> B33
     espage1000Count = COUNT of rows where shutterHeight in (1065,1265) -> C33
     fs10Count       = COUNT of rows where Width in (760,1066)          -> D33
     fs12Count       = COUNT of rows where Width in (1065,1301)         -> E33

   Hardware:
     casmentHandel  = windowCount * 2                                  -> G14
     espage800      = espage800Count * 2                               -> G15
     espage1000     = espage1000Count * 2                               -> G16
     frictionStay10 = fs10Count * 2                                    -> G17
     frictionStay12 = fs12Count * 2                                    -> G18
     gasFlatType    = ((opFramBars + opBeadBars + (mullionBars*2)) * 5850) / 1000 -> G19
     gasZeroType    = (opSashBars * 5850) / 1000                        -> G20
     gasZeroNonType = gasZeroType                                       -> G21 (=G20)
   ------------------------------------------------------------------
   NOTE: opFramBars, opSashBars, opBeadBars, mullionBars, framSteel,
   sashSteel, totalSqft and all hardware quantities depend on column
   SUMs/COUNTs across ALL rows, so they are computed once per order
   (totals), not per-window.
   ------------------------------------------------------------------ */

const computeWindow = (w) => {
  const width = Number(w.width) || 0;
  const height = Number(w.height) || 0;

  const shutterWidth = width === 0 ? 0 : width / 2 - 37;
  const shutterHeight = height === 0 ? 0 : height - 60;
  const mullionHeight = height === 0 ? 0 : height - 82;
  const framWidth = width === 0 ? 0 : width - 90;
  const sashWidth = shutterWidth === 0 ? 0 : shutterWidth - 125;
  const glassWidth = shutterWidth === 0 ? 0 : shutterWidth - 125;
  const glassHeight = shutterHeight === 0 ? 0 : shutterHeight - 125;
  // Op sash -> 2 glass panes per window
  const glassNos = glassWidth === 0 ? 0 : 2;

  const sqft =
    glassWidth === 0
      ? 0
      : (Math.ceil((glassWidth / 304.8) * 4) / 4) *
        (Math.ceil((glassHeight / 304.8) * 4) / 4);

  return {
    shutterWidth,
    shutterHeight,
    mullionHeight,
    framWidth,
    sashWidth,
    glassWidth,
    glassHeight,
    glassNos,
    sqft,
  };
};

// Order-level totals (mirrors row 17 / 33 of the OP-OP sheet)
const computeTotals = (results) => {
  const sumWidth = results.reduce((acc, r) => acc + (Number(r.width) || 0) * (Number(r.qty) || 1), 0);
  const sumHeight = results.reduce((acc, r) => acc + (Number(r.height) || 0) * (Number(r.qty) || 1), 0);
  const sumShutterWidth = results.reduce((acc, r) => acc + (r.shutterWidth || 0) * (Number(r.qty) || 1), 0);
  const sumShutterHeight = results.reduce((acc, r) => acc + (r.shutterHeight || 0) * (Number(r.qty) || 1), 0);
  const sumMullionHeight = results.reduce((acc, r) => acc + (r.mullionHeight || 0) * (Number(r.qty) || 1), 0);
  const sumFramWidth = results.reduce((acc, r) => acc + (r.framWidth || 0) * (Number(r.qty) || 1), 0);
  const sumSashWidth = results.reduce((acc, r) => acc + (r.sashWidth || 0) * (Number(r.qty) || 1), 0);
  const sumSqft = results.reduce((acc, r) => acc + (r.sqft || 0) * (Number(r.qty) || 1), 0);
  const windowCount = results.reduce((acc, r) => acc + (Number(r.qty) || 1), 0);

  const ceil1 = (x) => (x === 0 ? 0 : Math.ceil(x * 10) / 10);

  const opFramBars = ceil1(((sumWidth + sumHeight) * 2) / 5850);
  const opSashBars = ceil1((sumShutterWidth * 4 + sumShutterHeight * 4) / 5850);
  const opBeadBars = opSashBars;
  const mullionBars = ceil1(sumMullionHeight / 5850);
  const framSteel = ceil1((sumFramWidth * 2 + 500) / 2438);
  const sashSteel = ceil1((sumSashWidth * 4) / 2438);
  // Op sash -> multiply sqft total by 2
  const totalSqft = sumSqft * 2;

  const espage800Count = results.filter(
    (r) => r.shutterHeight > 845 && r.shutterHeight < 1066
  ).length;
  const espage1000Count = results.filter(
    (r) => r.shutterHeight > 1065 && r.shutterHeight < 1265
  ).length;
  const fs10Count = results.filter(
    (r) => (Number(r.width) || 0) > 760 && (Number(r.width) || 0) < 1066
  ).length;
  const fs12Count = results.filter(
    (r) => (Number(r.width) || 0) > 1065 && (Number(r.width) || 0) < 1301
  ).length;

  const casmentHandel = windowCount * 2;
  const espage800 = espage800Count * 2;
  const espage1000 = espage1000Count * 2;
  const frictionStay10 = fs10Count * 2;
  const frictionStay12 = fs12Count * 2;
  const gasFlatType = ((opFramBars + opBeadBars + mullionBars * 2) * 5850) / 1000;
  const gasZeroType = (opSashBars * 5850) / 1000;
  const gasZeroNonType = gasZeroType;

  return {
    windowCount,
    opFramBars,
    opSashBars,
    opBeadBars,
    mullionBars,
    framSteel,
    sashSteel,
    totalSqft,
    casmentHandel,
    espage800,
    espage1000,
    frictionStay10,
    frictionStay12,
    gasFlatType,
    gasZeroType,
    gasZeroNonType,
  };
};

