/* ------------------------------------------------------------------
   FORMULA LOGIC  (ported 1:1 from OP-OP-OP-OP / Profile & Hardwares sheets)
   ------------------------------------------------------------------
   Per-row (Width, Height inputs) — OP-OP-OP-OP sheet columns D/E/K/L/M:
     shutterWidth   = IF(Width=="", "", (Width / 4) - 25)           → D6
     shutterHeight  = IF(Height=="", "", (Height - 60))             → E6
     mullionHeight  = IF(Height=="", "", (Height - 82))             → K6  (Mullion Height col)
     framWidth      = IF(Width=="", "", (Width - 90))               → L6  (Fram Width col)
     sashWidth      = IF(shutterWidth=="", "", (shutterWidth - 125))→ M6  (Sash Width col)

   Glass sub-table (per-row, columns Q/R/S/T of OP-OP-OP-OP sheet):
     glassWidth     = IF(shutterWidth=="", "", shutterWidth - 125)  → Q6
     glassHeight    = IF(shutterHeight=="", "", shutterHeight - 125)→ R6
     glassNos       = IF(glassWidth=="", "", 4)                     → S6
     sqft           = CEILING(glassWidth/304.8, 0.25)
                      * CEILING(glassHeight/304.8, 0.25)            → V6  (Sq.ft)

   Order-level totals (row 17 / Profile Required table, column H):
     opFramBars  = CEILING(((SUM(Width)+SUM(Height))*2)/5850, 0.1)           → H6
     opSashBars  = CEILING(((SUM(shutterWidth)*6)+(SUM(shutterHeight)*6))/5850, 0.1) → H7
     opBeadBars  = opSashBars                                                 → H8 (=H7)
     mullionBars = CEILING((SUM(mullionHeight)*2)/5850, 0.1)                  → H9
     framSteel   = CEILING(((SUM(framWidth)*2)+500)/2438, 0.1)                → H11
     sashSteel   = CEILING((SUM(sashWidth)*6)/2438, 0.1)                      → H12
     totalSqft   = SUM(sqft) * 4                                              → Glass Total

     espage800Count  = COUNT rows where shutterHeight in (845,1066)            → B33
     espage1000Count = COUNT rows where shutterHeight in (1065,1265)           → C33
     fs10Count       = COUNT rows where Width in (1340,1616)                   → D33
     fs12Count       = COUNT rows where Width in (1615,2134)                   → E33

   Hardware (Profile & Hardwares sheet):
     casmentHandel = windowCount * 3                                           → G14
     espage800     = espage800Count * 3                                        → G15
     espage1000    = espage1000Count * 3                                       → G16
     frictionStay10 = fs10Count * 3                                            → G17
     frictionStay12 = fs12Count * 3                                            → G18
     gasFlatType   = ((opFramBars + (mullionBars*2) + opBeadBars)*5900)/1000  → G19
     gasZeroType   = (opSashBars * 5900) / 1000                               → G20
     gasZeroNonType = gasZeroType                                              → G21 (=G20)
   ------------------------------------------------------------------ */

const computeWindow = (w) => {
  const width = Number(w.width) || 0;
  const height = Number(w.height) || 0;

  // 4-panel OP sash: Width / 4 - 25
  const shutterWidth = width === 0 ? 0 : width / 4 - 25;
  const shutterHeight = height === 0 ? 0 : height - 60;
  // Mullion col (K): Height - 82
  const mullionHeight = height === 0 ? 0 : height - 82;
  // Fram Width col (L): Width - 90
  const framWidth = width === 0 ? 0 : width - 90;
  // Sash Width col (M): shutterWidth - 125
  const sashWidth = shutterWidth === 0 ? 0 : shutterWidth - 125;
  // Glass sub-table
  const glassWidth = shutterWidth === 0 ? 0 : shutterWidth - 125;
  const glassHeight = shutterHeight === 0 ? 0 : shutterHeight - 125;
  const glassNos = glassWidth === 0 ? 0 : 4;
  const sqft =
    glassWidth === 0
      ? 0
      : (Math.ceil((glassWidth / 304.8) * 4) / 4) *
        (Math.ceil((glassHeight / 304.8) * 4) / 4);

  return {
    shutterWidth,
    shutterHeight,
    mullionHeight,
    framWidth,
    sashWidth,
    glassWidth,
    glassHeight,
    glassNos,
    sqft,
  };
};

// Order-level totals (mirrors row 17 / row 33 of OP-OP-OP-OP sheet)
const computeTotals = (results) => {
  const sumWidth = results.reduce((acc, r) => acc + (Number(r.width) || 0) * (Number(r.qty) || 1), 0);
  const sumHeight = results.reduce((acc, r) => acc + (Number(r.height) || 0) * (Number(r.qty) || 1), 0);
  const sumShutterWidth = results.reduce((acc, r) => acc + (r.shutterWidth || 0) * (Number(r.qty) || 1), 0);
  const sumShutterHeight = results.reduce((acc, r) => acc + (r.shutterHeight || 0) * (Number(r.qty) || 1), 0);
  const sumMullionHeight = results.reduce((acc, r) => acc + (r.mullionHeight || 0) * (Number(r.qty) || 1), 0);
  const sumFramWidth = results.reduce((acc, r) => acc + (r.framWidth || 0) * (Number(r.qty) || 1), 0);
  const sumSashWidth = results.reduce((acc, r) => acc + (r.sashWidth || 0) * (Number(r.qty) || 1), 0);
  const sumSqft = results.reduce((acc, r) => acc + (r.sqft || 0) * (Number(r.qty) || 1), 0);
  const windowCount = results.reduce((acc, r) => acc + (Number(r.qty) || 1), 0);

  const ceil1 = (x) => (x === 0 ? 0 : Math.ceil(x * 10) / 10);

  const opFramBars = ceil1(((sumWidth + sumHeight) * 2) / 5850);
  const opSashBars = ceil1((sumShutterWidth * 6 + sumShutterHeight * 6) / 5850);
  const opBeadBars = opSashBars;
  const mullionBars = ceil1((sumMullionHeight * 2) / 5850);
  const framSteel = ceil1((sumFramWidth * 2 + 500) / 2438);
  const sashSteel = ceil1((sumSashWidth * 6) / 2438);
  // 4-panel product: multiply sqft total by 4
  const totalSqft = sumSqft * 4;

  const espage800Count = results.filter(
    (r) => r.shutterHeight > 845 && r.shutterHeight < 1066
  ).length;
  const espage1000Count = results.filter(
    (r) => r.shutterHeight > 1065 && r.shutterHeight < 1265
  ).length;
  const fs10Count = results.filter(
    (r) => (Number(r.width) || 0) > 1340 && (Number(r.width) || 0) < 1616
  ).length;
  const fs12Count = results.filter(
    (r) => (Number(r.width) || 0) > 1615 && (Number(r.width) || 0) < 2134
  ).length;

  const casmentHandel = windowCount * 3;
  const espage800 = espage800Count * 3;
  const espage1000 = espage1000Count * 3;
  const frictionStay10 = fs10Count * 3;
  const frictionStay12 = fs12Count * 3;
  const gasFlatType = ((opFramBars + mullionBars * 2 + opBeadBars) * 5900) / 1000;
  const gasZeroType = (opSashBars * 5900) / 1000;
  const gasZeroNonType = gasZeroType;

  return {
    windowCount,
    opFramBars,
    opSashBars,
    opBeadBars,
    mullionBars,
    framSteel,
    sashSteel,
    totalSqft,
    casmentHandel,
    espage800,
    espage1000,
    frictionStay10,
    frictionStay12,
    gasFlatType,
    gasZeroType,
    gasZeroNonType,
  };
};

