/* ------------------------------------------------------------------
   FORMULA LOGIC  (ported 1:1 from "Single Open" & "Profile & Hardwares" sheets)
   ------------------------------------------------------------------
   Per-row (Width, Height inputs):
     shutterFramWidth  = IF(Width=="",  "", (Width - 60))          -> D col
     shutterFramHeight = IF(Height=="", "", (Height - 60))         -> E col
     sashHeight        = IF(Height=="", "", (Height - 90))         -> K col
     sashWidth         = IF(shutterFramHeight=="", "", (shutterFramHeight - 125)) -> L col
     glassWidth        = IF(shutterFramWidth=="",  "", (shutterFramWidth - 125))  -> O col
     glassHeight       = IF(shutterFramHeight=="", "", (shutterFramHeight - 125)) -> P col
     glassNos          = IF(glassWidth=="", "", 1)                 -> Q col (1 pane per window)
     sqft              = IF(glassWidth=="", "",
                           CEILING(glassWidth/304.8, 0.25) *
                           CEILING(glassHeight/304.8, 0.25))       -> T col

   Order-level totals:
     opFramBars  = CEILING(((SUM(Width)+SUM(Height))*2)/5850, 0.1)          -> H6
     opSashBars  = CEILING(((SUM(shutterFramWidth)*2 + SUM(shutterFramHeight)*2)/5850), 0.1) -> H7
     opBeadBars  = opSashBars                                               -> H8 (=H7)
     framSteel   = CEILING(((SUM(sashHeight)*2 + 500)/2438), 0.1)           -> H10
     sashSteel   = CEILING((SUM(sashWidth)*2/2438), 0.1)                    -> H11
     totalSqft   = SUM(sqft) * 2                                            -> T17

   Espage / Friction Stay (Espage & Friction stay Sizes table, rows 22-33):
     espage800Count  = COUNT rows where Height in (845+60, 1066+60) i.e. shutterFramHeight in (845,1066)  -> B33
     espage1000Count = COUNT rows where Height in (1065+60,1265+60) i.e. shutterFramHeight in (1065,1265) -> C33
     fs10Count       = COUNT rows where Width in (350+60, 491+60)   i.e. Width in (410, 550) -> D33
     fs12Count       = COUNT rows where Width in (490+60, 641+60)   i.e. Width in (550, 700) -> E33
     fs14Count       = COUNT rows where Width in (640+60, 841+60)   i.e. Width in (700, 900) -> F33

   Hardware (Profile & Hardwares):
     casmentHandel  = windowCount * 1                          -> G14 (= A17 = window count)
     espage800      = espage800Count                           -> G15
     espage1000     = espage1000Count                          -> G16
     frictionStay10 = fs10Count                               -> G17
     frictionStay12 = fs12Count                               -> G18
     gasFlatType    = ((opFramBars + opBeadBars) * 5900)/1000 -> G19 (=(C5+C9)*5900/1000)
     gasZeroType    = (opSashBars * 5900)/1000                -> G20 (=(C8)*5900/1000)
     gasZeroNonType = gasZeroType                             -> G21 (=G20)
   ------------------------------------------------------------------ */

const computeWindow = (w) => {
  const width = Number(w.width) || 0;
  const height = Number(w.height) || 0;

  const shutterFramWidth  = width  === 0 ? 0 : width  - 60;
  const shutterFramHeight = height === 0 ? 0 : height - 60;
  const sashHeight        = height === 0 ? 0 : height - 90;
  const sashWidth         = shutterFramHeight === 0 ? 0 : shutterFramHeight - 125;
  const glassWidth        = shutterFramWidth  === 0 ? 0 : shutterFramWidth  - 125;
  const glassHeight       = shutterFramHeight === 0 ? 0 : shutterFramHeight - 125;
  const glassNos          = glassWidth === 0 ? 0 : 1;

  const sqft =
    glassWidth === 0
      ? 0
      : (Math.ceil((glassWidth / 304.8) * 4) / 4) *
        (Math.ceil((glassHeight / 304.8) * 4) / 4);

  return {
    shutterFramWidth,
    shutterFramHeight,
    sashHeight,
    sashWidth,
    glassWidth,
    glassHeight,
    glassNos,
    sqft,
  };
};

// Order-level totals (mirrors row 17 / row 33 of "Single Open" sheet)
const computeTotals = (results) => {
  const sumWidth             = results.reduce((a, r) => a + (Number(r.width)  || 0), 0);
  const sumHeight            = results.reduce((a, r) => a + (Number(r.height) || 0), 0);
  const sumShutterFramWidth  = results.reduce((a, r) => a + (r.shutterFramWidth  || 0), 0);
  const sumShutterFramHeight = results.reduce((a, r) => a + (r.shutterFramHeight || 0), 0);
  const sumSashHeight        = results.reduce((a, r) => a + (r.sashHeight || 0), 0);
  const sumSashWidth         = results.reduce((a, r) => a + (r.sashWidth  || 0), 0);
  const sumSqft              = results.reduce((a, r) => a + (r.sqft || 0), 0);
  const windowCount          = results.length;

  const ceil1 = (x) => (x === 0 ? 0 : Math.ceil(x * 10) / 10);

  const opFramBars = ceil1(((sumWidth + sumHeight) * 2) / 5850);
  const opSashBars = ceil1(((sumShutterFramWidth * 2) + (sumShutterFramHeight * 2)) / 5850);
  const opBeadBars = opSashBars;
  const framSteel  = ceil1((sumSashHeight * 2 + 500) / 2438);
  const sashSteel  = ceil1((sumSashWidth  * 2) / 2438);
  // Top-Hung single-sash: multiply sqft by 2 (1 pane × 2 faces of glass)
  const totalSqft  = sumSqft * 2;

  // Espage & Friction Stay size categorisation (based on shutterFramHeight / Width)
  const espage800Count  = results.filter((r) => r.shutterFramHeight > 845  && r.shutterFramHeight < 1066).length;
  const espage1000Count = results.filter((r) => r.shutterFramHeight > 1065 && r.shutterFramHeight < 1265).length;
  const fs10Count       = results.filter((r) => (Number(r.width) || 0) > 350 && (Number(r.width) || 0) < 491).length;
  const fs12Count       = results.filter((r) => (Number(r.width) || 0) > 490 && (Number(r.width) || 0) < 641).length;
  const fs14Count       = results.filter((r) => (Number(r.width) || 0) > 640 && (Number(r.width) || 0) < 841).length;

  // Hardware
  const casmentHandel  = windowCount;                              // G14 = A17
  const espage800      = espage800Count;
  const espage1000     = espage1000Count;
  const frictionStay10 = fs10Count;
  const frictionStay12 = fs12Count;
  const frictionStay14 = fs14Count;
  const gasFlatType    = ((opFramBars + opBeadBars) * 5900) / 1000;  // G19 = (C5+C9)*5900/1000
  const gasZeroType    = (opSashBars * 5900) / 1000;                 // G20 = C8*5900/1000
  const gasZeroNonType = gasZeroType;                                 // G21 = G20

  return {
    windowCount,
    opFramBars,
    opSashBars,
    opBeadBars,
    framSteel,
    sashSteel,
    totalSqft,
    casmentHandel,
    espage800,
    espage1000,
    frictionStay10,
    frictionStay12,
    frictionStay14,
    gasFlatType,
    gasZeroType,
    gasZeroNonType,
  };
};

