  { key: "mullionHeight", name: "mullionHeight", formula: "IF(Height==0,0,Height+30)" },
  { key: "framWidth", name: "framWidth", formula: "IF(Width==0,0,Width-90)" },
  { key: "sashWidth", name: "sashWidth", formula: "IF(shutterWidth==0,0,shutterWidth-115)" },
  { key: "glassWidth", name: "glassWidth", formula: "IF(shutterWidth==0,0,shutterWidth-118)" },
