/* ------------------------------------------------------------------
   FORMULA LOGIC  (ported 1:1 from FIX / Material & Hardware sheets)
   ------------------------------------------------------------------
   opBeadCut    = IF(Width==0, 0, (Width/2) - 37)            -> FIX!D6
   fixFrameBars = CEILING(((Width+Height)*2*Qty)/5850, 0.1)  -> FIX!H6
   opBeadBars   = fixFrameBars                                -> FIX!H7 (= H6)
   ------------------------------------------------------------------ */

const computeWindow = (w) => {
  const width = Number(w.width) || 0;
  const height = Number(w.height) || 0;
  const qty = Number(w.qty) || 0;

  const opBeadCut = width === 0 ? 0 : width / 2 - 37;

  const rawBars = ((width + height) * 2 * qty) / 5850;
  const fixFrameBars = rawBars === 0 ? 0 : Math.ceil(rawBars * 10) / 10;
  const opBeadBars = fixFrameBars;

  return { opBeadCut, fixFrameBars, opBeadBars };
};

