    setWindows((prev) =>
      prev.map((w) => (w.id === id ? { ...w, [field]: value } : w))
    );
  };

  const addWindow = () => {
    const nextNum = windows.length + 1;
    setWindows((prev) => [
      ...prev,
      { id: Date.now(), wno: `W${nextNum}`, qty: "", width: "", height: "" },
    ]);
